(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-trap-c5-basic-3"]={"id":"unit31-trap-c5-basic-3","unitId":"3-1","chapterIds":["3-1"],"unitType":"basic","group":"3-1단원 · 선지 변형 유형 · 조건","name":"기본 OX 3","level":"기본","revision":3,"resetReviewOnRevision":true,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"조건","parts":[{"name":"U31-H13-05-B2 · 행동으로 보여 주는 관심","items":[{"paragraphCount":1,"readingLabel":"13문단 · 핵심 읽기 5/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 13문단","passage":"[문단 전체 · 13문단]\n한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다. 첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다. 만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다. 이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다. 책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다. 세 번째는 ‘존경’이다. 존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다. 존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다. 존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"꽃을 사랑한다고 말해도 물을 주지 않으면 그 말을 믿기 어렵다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.”","evidence":{"title":"행동으로 보여 주는 관심","statement":"상대를 향한 관심은 상대가 살아가고 성장하도록 돌보는 행동에서 드러난다.","explanation":"꽃을 사랑한다고 말해도 물을 주지 않으면 그 말을 믿기 어렵다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.”","valid":["R13:2","R13:3"],"sources":[{"id":"R13","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"13문단","sentences":[{"id":"R13:1","text":"한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다.","paragraph":0,"memberIds":["R13:1"],"topic":"또 프롬은 성숙한 사랑에 세 가지 요소가 있다고 했다."},{"id":"R13:2","text":"첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.","paragraph":0,"memberIds":["R13:2"],"topic":"첫째는 '적극적인 관심'이다. 내가 사랑하는 상대가 살아가고 자라는 것(생명과 성장)에 적극적으로 마음을 쓰는 것이다."},{"id":"R13:3","text":"만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.","paragraph":0,"memberIds":["R13:3"],"topic":"어떤 사람이 꽃을 사랑한다고 말하면서, 꽃에 물 주는 것을 잊고 있다고 해 보자. 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다."},{"id":"R13:4","text":"이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다.","paragraph":0,"memberIds":["R13:4"],"topic":"이렇게 보호하고 관심을 갖는 것 안에는 사랑의 두 번째 요소인 '책임'이 들어 있다."},{"id":"R13:5","text":"책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.","paragraph":0,"memberIds":["R13:5"],"topic":"책임은 상대가 무언가를 바랄(요구할) 때 응답할 준비가 되어 있는 것이다. 그리고 상대가 잘한 일도 잘못한 일도 함께하려는 것이다."},{"id":"R13:6","text":"세 번째는 ‘존경’이다.","paragraph":0,"memberIds":["R13:6"],"topic":"세 번째는 '존경'이다."},{"id":"R13:7","text":"존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.","paragraph":0,"memberIds":["R13:7"],"topic":"존경한다는 것은 그 사람만의 독특한 개성을 꿰뚫어 보고(통찰하고) 존중하는 것이다."},{"id":"R13:8","text":"존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.","paragraph":0,"memberIds":["R13:8"],"topic":"존경은 상대가 그 사람 자신으로서(그 사람답게) 자라고 발전하기를 바라는 관심이다."},{"id":"R13:9","text":"존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","paragraph":0,"memberIds":["R13:9"],"topic":"존경이 빠지면(결여되면), 책임은 쉽게 상대를 내 마음대로 하고 내 것으로 삼으려는 욕심으로 떨어진다(전락한다)."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R13:2","text":"첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다."},{"id":"R13:3","text":"만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H13-05-B2","type":"ox","answer":"X","changed":"상대를 향한 관심은 사랑한다고 말하기만 해도 충분히 드러난다.","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","claimEdits":[{"start":11,"end":29,"before":"사랑한다고 말하기만 해도 충분히 ","after":"상대가 살아가고 성장하도록 돌보는 행동에서 "}],"progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"행동으로 보여 주는 관심","hintGuide":"꽃에 대한 사랑을 말만 하는 것과 물을 주는 것 중 무엇으로 확인하는지 보세요.","synthesis":true,"editorSourceVersion":"b66842071550a20f82a8aeaa56741ca41a4bb613249f93853da025cc247a7eba"}]},{"name":"U31-E06-B1 · 조건","items":[{"paragraphCount":2,"readingLabel":"12문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 12문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 12문단]\n주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다. 인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다. 이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다. 타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준은 동료가 다 해 주길 바라거나 자기 기록만 챙기거나 동료를 이용하지 않는다. 자기 플레이에 만족하며 편하게 패스한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 만족한다. 남에게 의지하거나 남을 지배하지 않아도 자기 삶에 만족할 때 진정한 사랑이 가능하다는 설명과 닮았다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.” “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.” “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","evidence":{"title":"독립적인 선수","statement":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 자기 플레이에 만족한다.","explanation":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 만족한다. 남에게 의지하거나 남을 지배하지 않아도 자기 삶에 만족할 때 진정한 사랑이 가능하다는 설명과 닮았다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.” “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.” “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","valid":["R12:2","R12:3","R12:4"],"sources":[{"id":"R12","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"12문단","sentences":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.","paragraph":0,"memberIds":["R12:1"],"topic":"'주는' 사랑을 할 수 있는 사람은 사람됨(인격)이 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","paragraph":0,"memberIds":["R12:2"],"topic":"인격이 성숙한 사람은 세 가지를 이겨 낸(극복한) 사람이다. 남에게 기대고 싶어 하는 마음(의존), 나에게만 빠져 있는 마음(나르시시즘), 남의 것을 빼앗아 이용하려는 욕심(착취)이다."},{"id":"R12:3","text":"이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.","paragraph":0,"memberIds":["R12:3"],"topic":"이런 성향들을 이겨 내지 못하면, 사람은 사랑을 주는 것을 두려워한다."},{"id":"R12:4","text":"타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","paragraph":0,"memberIds":["R12:4"],"topic":"남을 존중하는 진짜 사랑은 내가 독립적인 사람일 때만 할 수 있다. 다시 말해, 남에게 기대거나 남을 마음대로 하고 이용하지 않아도 내 삶에 만족할 수 있을 때만 가능하다."}]}]},"examplePractice":true,"id":"U31-E06-B1","type":"ox","answer":"O","changed":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 자기 플레이에 만족한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"a576676e610535aaea8521eb853f78a3bed26e41d0e6118ba01cfa12b6a624b5"}]},{"name":"U31-E06-B2 · 조건","items":[{"paragraphCount":2,"readingLabel":"12문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 12문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 12문단]\n주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다. 인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다. 이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다. 타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준은 동료가 다 해 주길 바라거나 자기 기록만 챙기거나 동료를 이용하지 않는다. 자기 플레이에 만족하며 편하게 패스한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 만족한다. 남에게 의지하거나 남을 지배하지 않아도 자기 삶에 만족할 때 진정한 사랑이 가능하다는 설명과 닮았다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.” “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.” “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","evidence":{"title":"독립적인 선수","statement":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 자기 플레이에 만족한다.","explanation":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 만족한다. 남에게 의지하거나 남을 지배하지 않아도 자기 삶에 만족할 때 진정한 사랑이 가능하다는 설명과 닮았다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.” “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.” “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","valid":["R12:2","R12:3","R12:4"],"sources":[{"id":"R12","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"12문단","sentences":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.","paragraph":0,"memberIds":["R12:1"],"topic":"'주는' 사랑을 할 수 있는 사람은 사람됨(인격)이 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","paragraph":0,"memberIds":["R12:2"],"topic":"인격이 성숙한 사람은 세 가지를 이겨 낸(극복한) 사람이다. 남에게 기대고 싶어 하는 마음(의존), 나에게만 빠져 있는 마음(나르시시즘), 남의 것을 빼앗아 이용하려는 욕심(착취)이다."},{"id":"R12:3","text":"이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.","paragraph":0,"memberIds":["R12:3"],"topic":"이런 성향들을 이겨 내지 못하면, 사람은 사랑을 주는 것을 두려워한다."},{"id":"R12:4","text":"타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","paragraph":0,"memberIds":["R12:4"],"topic":"남을 존중하는 진짜 사랑은 내가 독립적인 사람일 때만 할 수 있다. 다시 말해, 남에게 기대거나 남을 마음대로 하고 이용하지 않아도 내 삶에 만족할 수 있을 때만 가능하다."}]}]},"examplePractice":true,"id":"U31-E06-B2","type":"ox","answer":"X","changed":"하준은 동료를 자기 뜻대로 움직여야만 자기 플레이에 만족한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":0,"end":4,"before":"하준은 ","after":"하준은 동료에게 의지하거나 "},{"start":8,"end":21,"before":"자기 뜻대로 움직여야만 ","after":"이용하지 않아도 "}],"editorSourceVersion":"0fb76add9d9ec80b2816c1a3c459a166a732adfad82de97a191ad33cb5832366"}]},{"name":"U31-E07-B1 · 조건","items":[{"paragraphCount":2,"readingLabel":"13문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 13문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 13문단]\n한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다. 첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다. 만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다. 이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다. 책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다. 세 번째는 ‘존경’이다. 존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다. 존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다. 존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n주장은 후배의 컨디션을 살피고 도움 요청에 응답한다. 후배의 왼발 드리블을 존중하며 자기 방식을 강요하지 않는다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"후배의 컨디션을 살피는 것은 관심이다. 도움 요청에 응하는 것은 책임이다. 후배의 드리블 방식을 존중하는 것은 존경이다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.” “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.” “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”\n13문단에서 확인할 수 있어요.","evidence":{"title":"후배를 존중하는 주장","statement":"주장은 후배를 돌보고 도움을 요청하면 돕는다. 후배만의 개성도 존중한다.","explanation":"후배의 컨디션을 살피는 것은 관심이다. 도움 요청에 응하는 것은 책임이다. 후배의 드리블 방식을 존중하는 것은 존경이다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.” “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.” “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”\n13문단에서 확인할 수 있어요.","valid":["R13:2","R13:5","R13:7","R13:9"],"sources":[{"id":"R13","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"13문단","sentences":[{"id":"R13:1","text":"한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다.","paragraph":0,"memberIds":["R13:1"],"topic":"또 프롬은 성숙한 사랑에 세 가지 요소가 있다고 했다."},{"id":"R13:2","text":"첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.","paragraph":0,"memberIds":["R13:2"],"topic":"첫째는 '적극적인 관심'이다. 내가 사랑하는 상대가 살아가고 자라는 것(생명과 성장)에 적극적으로 마음을 쓰는 것이다."},{"id":"R13:3","text":"만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.","paragraph":0,"memberIds":["R13:3"],"topic":"어떤 사람이 꽃을 사랑한다고 말하면서, 꽃에 물 주는 것을 잊고 있다고 해 보자. 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다."},{"id":"R13:4","text":"이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다.","paragraph":0,"memberIds":["R13:4"],"topic":"이렇게 보호하고 관심을 갖는 것 안에는 사랑의 두 번째 요소인 '책임'이 들어 있다."},{"id":"R13:5","text":"책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.","paragraph":0,"memberIds":["R13:5"],"topic":"책임은 상대가 무언가를 바랄(요구할) 때 응답할 준비가 되어 있는 것이다. 그리고 상대가 잘한 일도 잘못한 일도 함께하려는 것이다."},{"id":"R13:6","text":"세 번째는 ‘존경’이다.","paragraph":0,"memberIds":["R13:6"],"topic":"세 번째는 '존경'이다."},{"id":"R13:7","text":"존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.","paragraph":0,"memberIds":["R13:7"],"topic":"존경한다는 것은 그 사람만의 독특한 개성을 꿰뚫어 보고(통찰하고) 존중하는 것이다."},{"id":"R13:8","text":"존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.","paragraph":0,"memberIds":["R13:8"],"topic":"존경은 상대가 그 사람 자신으로서(그 사람답게) 자라고 발전하기를 바라는 관심이다."},{"id":"R13:9","text":"존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","paragraph":0,"memberIds":["R13:9"],"topic":"존경이 빠지면(결여되면), 책임은 쉽게 상대를 내 마음대로 하고 내 것으로 삼으려는 욕심으로 떨어진다(전락한다)."}]}]},"examplePractice":true,"id":"U31-E07-B1","type":"ox","answer":"O","changed":"주장은 후배를 돌보고 도움을 요청하면 돕는다. 후배만의 개성도 존중한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"4bee3cd46b7c792871a6b86685db8ddfbb50beb9b95fa59c6977d90dd72bb512"}]},{"name":"U31-E07-B2 · 조건","items":[{"paragraphCount":2,"readingLabel":"13문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 13문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 13문단]\n한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다. 첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다. 만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다. 이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다. 책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다. 세 번째는 ‘존경’이다. 존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다. 존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다. 존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n주장은 후배의 컨디션을 살피고 도움 요청에 응답한다. 후배의 왼발 드리블을 존중하며 자기 방식을 강요하지 않는다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"후배의 컨디션을 살피는 것은 관심이다. 도움 요청에 응하는 것은 책임이다. 후배의 드리블 방식을 존중하는 것은 존경이다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.” “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.” “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”\n13문단에서 확인할 수 있어요.","evidence":{"title":"후배를 존중하는 주장","statement":"주장은 후배를 돌보고 도움을 요청하면 돕는다. 후배만의 개성도 존중한다.","explanation":"후배의 컨디션을 살피는 것은 관심이다. 도움 요청에 응하는 것은 책임이다. 후배의 드리블 방식을 존중하는 것은 존경이다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.” “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.” “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”\n13문단에서 확인할 수 있어요.","valid":["R13:2","R13:5","R13:7","R13:9"],"sources":[{"id":"R13","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"13문단","sentences":[{"id":"R13:1","text":"한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다.","paragraph":0,"memberIds":["R13:1"],"topic":"또 프롬은 성숙한 사랑에 세 가지 요소가 있다고 했다."},{"id":"R13:2","text":"첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.","paragraph":0,"memberIds":["R13:2"],"topic":"첫째는 '적극적인 관심'이다. 내가 사랑하는 상대가 살아가고 자라는 것(생명과 성장)에 적극적으로 마음을 쓰는 것이다."},{"id":"R13:3","text":"만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.","paragraph":0,"memberIds":["R13:3"],"topic":"어떤 사람이 꽃을 사랑한다고 말하면서, 꽃에 물 주는 것을 잊고 있다고 해 보자. 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다."},{"id":"R13:4","text":"이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다.","paragraph":0,"memberIds":["R13:4"],"topic":"이렇게 보호하고 관심을 갖는 것 안에는 사랑의 두 번째 요소인 '책임'이 들어 있다."},{"id":"R13:5","text":"책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.","paragraph":0,"memberIds":["R13:5"],"topic":"책임은 상대가 무언가를 바랄(요구할) 때 응답할 준비가 되어 있는 것이다. 그리고 상대가 잘한 일도 잘못한 일도 함께하려는 것이다."},{"id":"R13:6","text":"세 번째는 ‘존경’이다.","paragraph":0,"memberIds":["R13:6"],"topic":"세 번째는 '존경'이다."},{"id":"R13:7","text":"존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.","paragraph":0,"memberIds":["R13:7"],"topic":"존경한다는 것은 그 사람만의 독특한 개성을 꿰뚫어 보고(통찰하고) 존중하는 것이다."},{"id":"R13:8","text":"존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.","paragraph":0,"memberIds":["R13:8"],"topic":"존경은 상대가 그 사람 자신으로서(그 사람답게) 자라고 발전하기를 바라는 관심이다."},{"id":"R13:9","text":"존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","paragraph":0,"memberIds":["R13:9"],"topic":"존경이 빠지면(결여되면), 책임은 쉽게 상대를 내 마음대로 하고 내 것으로 삼으려는 욕심으로 떨어진다(전락한다)."}]}]},"examplePractice":true,"id":"U31-E07-B2","type":"ox","answer":"X","changed":"주장은 후배를 도우려면 후배만의 개성을 무시해야 한다고 생각한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":8,"end":13,"before":"도우려면 ","after":"돌보고 도움을 요청하면 돕는다. "},{"start":18,"end":36,"before":"개성을 무시해야 한다고 생각한다.","after":"개성도 존중한다."}],"editorSourceVersion":"72099765c4216960bab1bc7ae389830cc7a7110731cf32548ef1ac8cf18146d5"}]},{"name":"U31-P15-03-B1 · 조건","items":[{"paragraphCount":1,"readingLabel":"15문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 15문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 15문단]\n따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다. 어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다. 어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다. 진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","evidence":{"title":"인류와 분리된 사랑은 피상적이다.","statement":"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.","explanation":"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","valid":["R15:3"],"sources":[{"id":"R15","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"15문단","sentences":[{"id":"R15:1","text":"따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.","paragraph":0,"memberIds":["R15:1"],"topic":"그러니 성숙한 사랑은 '한' 사람, '하나의' 대상을 대하는 태도가 아니다. 세상 전체와 어떻게 관계를 맺을지 정하는 '태도', 곧 그 사람이 가진 '특정한 성격'이다."},{"id":"R15:2","text":"어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다.","paragraph":0,"memberIds":["R15:2"],"topic":"어떤 사람을 진짜로 사랑한다는 것은 그 사람의 인간으로서의 핵심과 관계를 맺는 것이다. 즉 그 사람을 '인류와 삶을 대표하는 한 사람'으로 대하는 것이다."},{"id":"R15:3","text":"어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.","paragraph":0,"memberIds":["R15:3"],"topic":"한 사람에 대한 사랑이 인류(모든 사람)에 대한 사랑과 따로 떨어져 있다면, 그 사랑은 겉만 보는(피상적인) 것일 뿐이다. 나만 챙기던 마음이 '우리'만 챙기는 마음으로 넓어진 것(확대된 이기주의)일 뿐이다."},{"id":"R15:4","text":"진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","paragraph":0,"memberIds":["R15:4"],"topic":"진짜 사랑은 스스로 정하는 힘(자율성)과 남에게 기대지 않는 성질(독립성)을 잃지 않으면서, 다른 사람·모든 인류·자연과 하나로 이어지는(결합) 경험을 하는 것이다."}]}]},"id":"U31-P15-03-B1","type":"ox","answer":"O","changed":"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"editorSourceVersion":"9e9800bf35f00c17422930c44e4da3cb8c419d7399c9e51df21901b2dc6867e9"}]},{"name":"U31-P15-03-B2 · 조건","items":[{"paragraphCount":1,"readingLabel":"15문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 15문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 15문단]\n따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다. 어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다. 어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다. 진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","evidence":{"title":"인류와 분리된 사랑은 피상적이다.","statement":"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.","explanation":"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없다면, 그 사랑은 깊이 없는 사랑이다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”\n15문단에서 확인할 수 있어요.","valid":["R15:3"],"sources":[{"id":"R15","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"15문단","sentences":[{"id":"R15:1","text":"따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.","paragraph":0,"memberIds":["R15:1"],"topic":"그러니 성숙한 사랑은 '한' 사람, '하나의' 대상을 대하는 태도가 아니다. 세상 전체와 어떻게 관계를 맺을지 정하는 '태도', 곧 그 사람이 가진 '특정한 성격'이다."},{"id":"R15:2","text":"어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다.","paragraph":0,"memberIds":["R15:2"],"topic":"어떤 사람을 진짜로 사랑한다는 것은 그 사람의 인간으로서의 핵심과 관계를 맺는 것이다. 즉 그 사람을 '인류와 삶을 대표하는 한 사람'으로 대하는 것이다."},{"id":"R15:3","text":"어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.","paragraph":0,"memberIds":["R15:3"],"topic":"한 사람에 대한 사랑이 인류(모든 사람)에 대한 사랑과 따로 떨어져 있다면, 그 사랑은 겉만 보는(피상적인) 것일 뿐이다. 나만 챙기던 마음이 '우리'만 챙기는 마음으로 넓어진 것(확대된 이기주의)일 뿐이다."},{"id":"R15:4","text":"진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","paragraph":0,"memberIds":["R15:4"],"topic":"진짜 사랑은 스스로 정하는 힘(자율성)과 남에게 기대지 않는 성질(독립성)을 잃지 않으면서, 다른 사람·모든 인류·자연과 하나로 이어지는(결합) 경험을 하는 것이다."}]}]},"id":"U31-P15-03-B2","type":"ox","answer":"X","changed":"한 사람을 좋아하면서 다른 사람들의 삶에는 관심이 없어도, 그 사랑은 성숙한 사랑이다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"claimEdits":[{"start":28,"end":33,"before":"없어도, ","after":"없다면, "},{"start":39,"end":43,"before":"성숙한 ","after":"깊이 없는 "}],"editorSourceVersion":"ad342cd20f84ea7b1890ef320003f70dca0cb9826ae7969e8c3a61dbda5bbe3d"}]},{"name":"U31-P15-05-B1 · 조건","items":[{"paragraphCount":1,"readingLabel":"15문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 15문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 15문단]\n따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다. 어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다. 어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다. 진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"진정으로 사랑하는 사람은 스스로 선택하고 독립적으로 살아간다. 그러면서 다른 사람과 인류, 자연과도 관계를 맺는다.\n근거: “진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.”\n15문단에서 확인할 수 있어요.","evidence":{"title":"결합해도 자율성과 독립성은 지킨다.","statement":"진정으로 사랑하는 사람은 스스로 선택하고 독립적으로 살아간다. 그러면서 다른 사람과 인류, 자연과도 관계를 맺는다.","explanation":"진정으로 사랑하는 사람은 스스로 선택하고 독립적으로 살아간다. 그러면서 다른 사람과 인류, 자연과도 관계를 맺는다.\n근거: “진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.”\n15문단에서 확인할 수 있어요.","valid":["R15:4"],"sources":[{"id":"R15","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"15문단","sentences":[{"id":"R15:1","text":"따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.","paragraph":0,"memberIds":["R15:1"],"topic":"그러니 성숙한 사랑은 '한' 사람, '하나의' 대상을 대하는 태도가 아니다. 세상 전체와 어떻게 관계를 맺을지 정하는 '태도', 곧 그 사람이 가진 '특정한 성격'이다."},{"id":"R15:2","text":"어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다.","paragraph":0,"memberIds":["R15:2"],"topic":"어떤 사람을 진짜로 사랑한다는 것은 그 사람의 인간으로서의 핵심과 관계를 맺는 것이다. 즉 그 사람을 '인류와 삶을 대표하는 한 사람'으로 대하는 것이다."},{"id":"R15:3","text":"어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.","paragraph":0,"memberIds":["R15:3"],"topic":"한 사람에 대한 사랑이 인류(모든 사람)에 대한 사랑과 따로 떨어져 있다면, 그 사랑은 겉만 보는(피상적인) 것일 뿐이다. 나만 챙기던 마음이 '우리'만 챙기는 마음으로 넓어진 것(확대된 이기주의)일 뿐이다."},{"id":"R15:4","text":"진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","paragraph":0,"memberIds":["R15:4"],"topic":"진짜 사랑은 스스로 정하는 힘(자율성)과 남에게 기대지 않는 성질(독립성)을 잃지 않으면서, 다른 사람·모든 인류·자연과 하나로 이어지는(결합) 경험을 하는 것이다."}]}]},"id":"U31-P15-05-B1","type":"ox","answer":"O","changed":"진정으로 사랑하는 사람은 스스로 선택하고 독립적으로 살아간다. 그러면서 다른 사람과 인류, 자연과도 관계를 맺는다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"editorSourceVersion":"60c5c6d2a6c36c56acffd3c4de080adc7f4bf14b58e8df2b32fae90fc28327f8"}]},{"name":"U31-P15-05-B2 · 조건","items":[{"paragraphCount":1,"readingLabel":"15문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 15문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 15문단]\n따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다. 어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다. 어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다. 진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"진정으로 사랑하는 사람은 스스로 선택하고 독립적으로 살아간다. 그러면서 다른 사람과 인류, 자연과도 관계를 맺는다.\n근거: “진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.”\n15문단에서 확인할 수 있어요.","evidence":{"title":"결합해도 자율성과 독립성은 지킨다.","statement":"진정으로 사랑하는 사람은 스스로 선택하고 독립적으로 살아간다. 그러면서 다른 사람과 인류, 자연과도 관계를 맺는다.","explanation":"진정으로 사랑하는 사람은 스스로 선택하고 독립적으로 살아간다. 그러면서 다른 사람과 인류, 자연과도 관계를 맺는다.\n근거: “진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.”\n15문단에서 확인할 수 있어요.","valid":["R15:4"],"sources":[{"id":"R15","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"15문단","sentences":[{"id":"R15:1","text":"따라서 성숙한 사랑은 ‘한’ 사람 내지, ‘하나의’ 대상에 대한 태도가 아니라 세계 전체와의 관계를 결정하는 ‘태도’, 곧 ‘특정한 성격’이다.","paragraph":0,"memberIds":["R15:1"],"topic":"그러니 성숙한 사랑은 '한' 사람, '하나의' 대상을 대하는 태도가 아니다. 세상 전체와 어떻게 관계를 맺을지 정하는 '태도', 곧 그 사람이 가진 '특정한 성격'이다."},{"id":"R15:2","text":"어떤 사람을 진정 사랑한다는 것은 그 사람의 인간적인 핵심, 즉 인류와 삶을 대표하는 자로서의 그 사람과 관계하는 것을 의미한다.","paragraph":0,"memberIds":["R15:2"],"topic":"어떤 사람을 진짜로 사랑한다는 것은 그 사람의 인간으로서의 핵심과 관계를 맺는 것이다. 즉 그 사람을 '인류와 삶을 대표하는 한 사람'으로 대하는 것이다."},{"id":"R15:3","text":"어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.","paragraph":0,"memberIds":["R15:3"],"topic":"한 사람에 대한 사랑이 인류(모든 사람)에 대한 사랑과 따로 떨어져 있다면, 그 사랑은 겉만 보는(피상적인) 것일 뿐이다. 나만 챙기던 마음이 '우리'만 챙기는 마음으로 넓어진 것(확대된 이기주의)일 뿐이다."},{"id":"R15:4","text":"진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","paragraph":0,"memberIds":["R15:4"],"topic":"진짜 사랑은 스스로 정하는 힘(자율성)과 남에게 기대지 않는 성질(독립성)을 잃지 않으면서, 다른 사람·모든 인류·자연과 하나로 이어지는(결합) 경험을 하는 것이다."}]}]},"id":"U31-P15-05-B2","type":"ox","answer":"X","changed":"진정으로 사랑하는 사람은 스스로 선택할 자유와 독립성을 버려야 한다. 그래야 다른 사람과 인류, 자연과 관계를 맺는다.","ask":"다음 설명이 지문과 같으면 O, 다르면 X를 고르세요.","requiresEvidence":false,"highlightEvidence":true,"claimEdits":[{"start":18,"end":43,"before":"선택할 자유와 독립성을 버려야 한다. 그래야 ","after":"선택하고 독립적으로 살아간다. 그러면서 "},{"start":54,"end":58,"before":"자연과 ","after":"자연과도 "}],"editorSourceVersion":"1b1cb15ee6c7a9af2d901e53a882edbbc9856bb7c8c43ec5324617b45f1a29b9"}]},{"name":"U31-H14-04-B2 · 가까운 사랑과 넓은 관심","items":[{"paragraphCount":1,"readingLabel":"14문단 · 핵심 읽기 4/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 14문단","passage":"[핵심 문장 · 14문단]\n나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다. 예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"가까운 사람을 사랑하는 것과 다른 사람에게 관심을 갖는 것은 함께 할 수 있다.\n근거: “나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.” “예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다.”","evidence":{"title":"가까운 사랑과 넓은 관심","statement":"가까운 사람을 진정 사랑해도 타인에 대한 관심은 사라지지 않는다.","explanation":"가까운 사람을 사랑하는 것과 다른 사람에게 관심을 갖는 것은 함께 할 수 있다.\n근거: “나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.” “예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다.”","valid":["R14:1","R14:2"],"sources":[{"id":"R14","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"14문단","sentences":[{"id":"R14:1","text":"나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다.","paragraph":0,"memberIds":["R14:1"],"topic":"더 나아가 성숙한 사랑은 절대 한 사람에게만 머무르지(제한되지) 않는다."},{"id":"R14:2","text":"예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다.","paragraph":0,"memberIds":["R14:2"],"topic":"예를 들어 두 연인이 진짜로 사랑하고, 부모가 진짜로 자녀를 사랑한다고 하자. 그렇다고 그들이 다른 사람들에게 관심을 끊는(무관심해지는) 것은 아니다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R14:1","text":"나아가 성숙한 사랑은 결코 한 사람에게 제한되지 않는다."},{"id":"R14:2","text":"예를 들어 두 연인이 진정으로 사랑을 하고 부모가 진정으로 자녀를 사랑할 때, 그들은 그들 외의 다른 사람들에게 무관심하게 되는 것이 아니다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H14-04-B2","type":"ox","answer":"X","changed":"가까운 사람을 진정 사랑할수록 타인에 대한 관심은 사라진다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","claimEdits":[{"start":11,"end":17,"before":"사랑할수록 ","after":"사랑해도 "},{"start":28,"end":33,"before":"사라진다.","after":"사라지지 않는다."}],"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"가까운 사랑과 넓은 관심","hintGuide":"가까운 사람을 사랑하면 꼭 다른 사람에게 무관심해야 하는지 보세요.","synthesis":false,"editorSourceVersion":"bdeb058aa674cb330cf674c1418af8298401a8c5ce5d897d72c02b8773da9dce"}]},{"name":"U31-H15-01-B2 · 자율성의 유지","items":[{"paragraphCount":1,"readingLabel":"15문단 · 핵심 읽기 1/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 15문단","passage":"[핵심 문장 · 15문단]\n진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"다른 존재와 함께하면서도 자기 생각대로 선택하고 독립적으로 살아갈 수 있다.\n근거: “진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.”","evidence":{"title":"자율성의 유지","statement":"진정한 사랑을 하면서도 스스로 선택할 자유를 지킬 수 있다.","explanation":"다른 존재와 함께하면서도 자기 생각대로 선택하고 독립적으로 살아갈 수 있다.\n근거: “진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.”","valid":["R15:4"],"sources":[{"id":"R15","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"15문단","sentences":[{"id":"R15:4","text":"진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다.","paragraph":0,"memberIds":["R15:4"],"topic":"진짜 사랑은 스스로 정하는 힘(자율성)과 남에게 기대지 않는 성질(독립성)을 잃지 않으면서, 다른 사람·모든 인류·자연과 하나로 이어지는(결합) 경험을 하는 것이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R15:4","text":"진정한 의미의 사랑은 자신의 자율성과 독립성을 상실하지 않은 채 다른 사람과 모든 인류 그리고 자연과의 결합을 경험하는 것이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H15-01-B2","type":"ox","answer":"X","changed":"진정한 사랑을 하려면 스스로 선택할 자유를 버려야 한다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","claimEdits":[{"start":8,"end":12,"before":"하려면 ","after":"하면서도 "},{"start":24,"end":31,"before":"버려야 한다.","after":"지킬 수 있다."}],"progressiveComparison":true,"progressiveStep":1,"progressiveTotal":5,"progressiveLabel":"핵심 낱말과 사실","learningFocus":"자율성의 유지","hintGuide":"사랑할 때 자신의 자유와 독립성을 잃어야 하는지 보세요.","synthesis":false,"editorSourceVersion":"25948268c4a68bf194674c4c84f6e9f3747e71c3e86753f4aebf3643896d4545"}]},{"name":"U31-H15-04-B1 · 가까운 사람만 챙기는 사랑의 한계","items":[{"paragraphCount":1,"readingLabel":"15문단 · 핵심 읽기 4/5단계","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 15문단","passage":"[핵심 문장 · 15문단]\n어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"본문은 인류에 대한 사랑과 떨어진 개인 사랑을 확대된 이기주의라고 본다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”","evidence":{"title":"가까운 사람만 챙기는 사랑의 한계","statement":"인류를 사랑하지 않으면서 한 사람만 사랑한다면, 자기와 가까운 사람만 챙기는 이기심에 머무른다.","explanation":"본문은 인류에 대한 사랑과 떨어진 개인 사랑을 확대된 이기주의라고 본다.\n근거: “어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.”","valid":["R15:3"],"sources":[{"id":"R15","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"15문단","sentences":[{"id":"R15:3","text":"어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다.","paragraph":0,"memberIds":["R15:3"],"topic":"한 사람에 대한 사랑이 인류(모든 사람)에 대한 사랑과 따로 떨어져 있다면, 그 사랑은 겉만 보는(피상적인) 것일 뿐이다. 나만 챙기던 마음이 '우리'만 챙기는 마음으로 넓어진 것(확대된 이기주의)일 뿐이다."}]}]},"shortComparison":true,"focusQuotes":[{"id":"R15:3","text":"어떤 개인에 대한 사랑이 인류에 대한 사랑과 분리되어 있는 한, 그 개인에 대한 사랑이란 다만 피상적인 것일 뿐이며 확대된 이기주의일 뿐이다."}],"highlightEvidence":true,"requiresEvidence":false,"id":"U31-H15-04-B1","type":"ox","answer":"O","changed":"인류를 사랑하지 않으면서 한 사람만 사랑한다면, 자기와 가까운 사람만 챙기는 이기심에 머무른다.","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"가까운 사람만 챙기는 사랑의 한계","hintGuide":"한 사람을 사랑하면서도 그 밖의 사람을 외면하는 태도를 어떻게 보는지 보세요.","synthesis":false,"editorSourceVersion":"78190e9b83a099f7c9d940be0602d20fcd33062a9695b16f345aca1c40bf3cec"}]}]};})(window);
